INSERT INTO public.listings VALUES (1, 'trek', 'Everest Base Camp Trek', 'सगरमाथा आधार शिविर पदयात्रा', 'A legendary 12-day trek through Sherpa villages, culminating at the foot of the world''s highest mountain.', 'संसारको सर्वोच्च शिखर सगरमाथाको आधार शिविरसम्मको प्रसिद्ध पदयात्रा, शेर्पा गाउँ, गुम्बा र हिमाली दृश्यसहित।', 'Solukhumbu', 'Everest Region', 27.9881000, 86.9250000, 1450.00, 12, 10, 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Mount_Everest%27s_west_shoulder%2C_Mt._Everest%2C_Mt._Nuptse_near_EBC%2C_Nepal.jpg/1280px-Mount_Everest%27s_west_shoulder%2C_Mt._Everest%2C_Mt._Nuptse_near_EBC%2C_Nepal.jpg', '2026-09-25 11:49:05.445703', 'challenging', 5364, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Fly Kathmandu to Lukla, trek to Phakding"}, {"day": "2", "title": "Trek to Namche Bazaar"}, {"day": "3", "title": "Acclimatisation day in Namche Bazaar"}, {"day": "4", "title": "Trek to Tengboche"}, {"day": "5", "title": "Trek to Dingboche"}, {"day": "6", "title": "Acclimatisation day in Dingboche"}, {"day": "7", "title": "Trek to Lobuche"}, {"day": "8", "title": "Trek to Gorak Shep and Everest Base Camp"}, {"day": "9", "title": "Sunrise at Kala Patthar, descend to Pheriche"}, {"day": "10", "title": "Trek to Namche Bazaar"}, {"day": "11", "title": "Trek to Lukla"}, {"day": "12", "title": "Fly to Kathmandu"}]', '{"Kathmandu–Lukla return flights","Trekking permits","Licensed trekking guide","Teahouse accommodation"}', '{"International flights","Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Way_to_everest_base_camp.jpg/1280px-Way_to_everest_base_camp.jpg,https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Working_yaks_in_Everest_region.jpg/1280px-Working_yaks_in_Everest_region.jpg}', '[[27.6870, 86.7310], [27.8050, 86.7140], [27.8360, 86.7640], [27.8920, 86.8310], [27.9480, 86.8100], [27.9810, 86.8290], [28.0040, 86.8570]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Mount_Everest%27s_west_shoulder%2C_Mt._Everest%2C_Mt._Nuptse_near_EBC%2C_Nepal.jpg/1280px-Mount_Everest%27s_west_shoulder%2C_Mt._Everest%2C_Mt._Nuptse_near_EBC%2C_Nepal.jpg", "author": "Rohit Sharma", "source": "https://commons.wikimedia.org/wiki/File:Mount_Everest%27s_west_shoulder,_Mt._Everest,_Mt._Nuptse_near_EBC,_Nepal.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Way_to_everest_base_camp.jpg/1280px-Way_to_everest_base_camp.jpg", "author": "Babin Dulal", "source": "https://commons.wikimedia.org/wiki/File:Way_to_everest_base_camp.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Working_yaks_in_Everest_region.jpg/1280px-Working_yaks_in_Everest_region.jpg", "author": "TT4FT", "source": "https://commons.wikimedia.org/wiki/File:Working_yaks_in_Everest_region.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (2, 'trek', 'Annapurna Base Camp Trek', 'अन्नपूर्ण आधार शिविर पदयात्रा', 'A 7-day trek through rhododendron forests and terraced fields to the Annapurna Sanctuary.', 'गुराङ गाउँ, बाँसको जंगल र तातोपानी हुँदै अन्नपूर्ण हिमशृङ्खलाले घेरिएको आधार शिविरसम्मको पदयात्रा।', 'Pokhara', 'Annapurna Region', 28.5308000, 83.8794000, 850.00, 8, 12, 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Mt._Moditse_as_seen_from_Annapurna_Base_Camp-5324.jpg/1280px-Mt._Moditse_as_seen_from_Annapurna_Base_Camp-5324.jpg', '2026-09-25 11:49:05.445703', 'moderate', 4130, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Drive Pokhara to Nayapul, trek to Ghandruk"}, {"day": "2", "title": "Trek to Chhomrong"}, {"day": "3", "title": "Trek to Bamboo"}, {"day": "4", "title": "Trek to Deurali"}, {"day": "5", "title": "Trek to Annapurna Base Camp via Machhapuchhre Base Camp"}, {"day": "6", "title": "Sunrise at base camp, descend to Bamboo"}, {"day": "7", "title": "Trek to Jhinu Danda hot springs"}, {"day": "8", "title": "Trek to Nayapul, drive to Pokhara"}]', '{"Trekking permits","Licensed trekking guide","Teahouse accommodation","Pokhara–Nayapul transport"}', '{"International flights","Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Annapurna_Base_Camp_%289%29.JPG/1280px-Annapurna_Base_Camp_%289%29.JPG}', '[[28.2850, 83.7670], [28.3760, 83.8090], [28.4170, 83.8190], [28.4580, 83.8350], [28.4950, 83.8640], [28.5040, 83.8770], [28.5300, 83.8780]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Mt._Moditse_as_seen_from_Annapurna_Base_Camp-5324.jpg/1280px-Mt._Moditse_as_seen_from_Annapurna_Base_Camp-5324.jpg", "author": "Bijay Chaurasia", "source": "https://commons.wikimedia.org/wiki/File:Mt._Moditse_as_seen_from_Annapurna_Base_Camp-5324.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Annapurna_Base_Camp_%289%29.JPG/1280px-Annapurna_Base_Camp_%289%29.JPG", "author": "Bijaya2043", "source": "https://commons.wikimedia.org/wiki/File:Annapurna_Base_Camp_(9).JPG", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0"}]');
INSERT INTO public.listings VALUES (3, 'trek', 'Poon Hill Trek', 'पून हिल पदयात्रा', 'A shorter 4-day trek famous for sunrise views over the Annapurna and Dhaulagiri ranges.', 'अन्नपूर्ण र धौलागिरि हिमशृङ्खलामाथिको सूर्योदयका लागि प्रसिद्ध छोटो चार दिने पदयात्रा।', 'Pokhara', 'Ghorepani-Poon Hill', 28.3990000, 83.6997000, 320.00, 4, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Sunrise_from_Poon_Hill%2C_Ghorepani.jpg/1280px-Sunrise_from_Poon_Hill%2C_Ghorepani.jpg', '2026-09-25 11:49:05.445703', 'easy', 3210, 'Oct–Apr', 'असोजदेखि वैशाखसम्म', '[{"day": "1", "title": "Drive Pokhara to Nayapul, trek to Ulleri"}, {"day": "2", "title": "Trek to Ghorepani"}, {"day": "3", "title": "Sunrise at Poon Hill, trek to Tadapani"}, {"day": "4", "title": "Trek to Ghandruk, drive to Pokhara"}]', '{"Trekking permits","Licensed trekking guide","Teahouse accommodation","Pokhara–Nayapul transport"}', '{"Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Poon_hill_sunrise.jpg/1280px-Poon_hill_sunrise.jpg}', '[[28.2850, 83.7670], [28.3400, 83.7400], [28.4000, 83.7000], [28.3990, 83.6997], [28.3910, 83.7650], [28.3760, 83.8090]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Sunrise_from_Poon_Hill%2C_Ghorepani.jpg/1280px-Sunrise_from_Poon_Hill%2C_Ghorepani.jpg", "author": "Aditya Pal", "source": "https://commons.wikimedia.org/wiki/File:Sunrise_from_Poon_Hill,_Ghorepani.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Poon_hill_sunrise.jpg/1280px-Poon_hill_sunrise.jpg", "author": "Thapaliyashreeram", "source": "https://commons.wikimedia.org/wiki/File:Poon_hill_sunrise.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (4, 'hotel', 'Hotel Barahi', 'होटल बाराही', 'A lakeside luxury hotel with stunning views of the Annapurna range.', 'फेवा तालनजिकै लेकसाइडमा रहेको आरामदायी होटल, बगैंचा र पौडी पोखरीसहित।', 'Pokhara', 'Lakeside', 28.2096000, 83.9586000, 105.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Phewa_Lake_of_Pokhara_city.jpg/1280px-Phewa_Lake_of_Pokhara_city.jpg', '2026-09-25 11:50:15.417582', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Free Wi-Fi","Swimming pool",Restaurant,Garden,"Airport transfer","Breakfast available"}', 4, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Phewa_Lake_of_Pokhara_city.jpg/1280px-Phewa_Lake_of_Pokhara_city.jpg", "author": "Iamavinashk", "source": "https://commons.wikimedia.org/wiki/File:Phewa_Lake_of_Pokhara_city.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "area_caption": "Phewa Lake, Pokhara", "area_caption_np": "फेवा ताल, पोखरा"}]');
INSERT INTO public.listings VALUES (5, 'hotel', 'Dwarika''s Hotel', 'द्वारिकाज होटल', 'A heritage hotel in Kathmandu showcasing traditional Newari architecture.', 'परम्परागत नेवारी वास्तुकलामा बनेको काठमाडौंको सम्पदा होटल, कलात्मक आँगन र विलासी सेवासहित।', 'Kathmandu', 'Battisputali', 27.7089000, 85.3467000, 270.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Taleju_temple%2C_Patan_Durbar_Square.jpg/1280px-Taleju_temple%2C_Patan_Durbar_Square.jpg', '2026-09-25 11:50:15.417582', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Free Wi-Fi",Spa,"Swimming pool",Restaurant,Bar,"Airport transfer","Breakfast included"}', 5, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Taleju_temple%2C_Patan_Durbar_Square.jpg/1280px-Taleju_temple%2C_Patan_Durbar_Square.jpg", "author": "Shadow Ayush", "source": "https://commons.wikimedia.org/wiki/File:Taleju_temple,_Patan_Durbar_Square.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "area_caption": "Patan Durbar Square, Kathmandu Valley", "area_caption_np": "पाटन दरबार क्षेत्र, काठमाडौं उपत्यका"}]');
INSERT INTO public.listings VALUES (6, 'hotel', 'Yeti Mountain Home', 'यती माउन्टेन होम', 'A cozy mountain lodge along the Everest trekking route.', 'खुम्बु क्षेत्रमा पदयात्रीहरूका लागि आरामदायी पहाडी लज, हिमाली दृश्य र तातो खानासहित।', 'Solukhumbu', 'Namche Bazaar', 27.8069000, 86.7139000, 190.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Namche_Bazaar%2C_Mountains%2C_Nepal.jpg/1280px-Namche_Bazaar%2C_Mountains%2C_Nepal.jpg', '2026-09-25 11:50:15.417582', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Heated rooms",Restaurant,"Mountain views","Breakfast included"}', NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Namche_Bazaar%2C_Mountains%2C_Nepal.jpg/1280px-Namche_Bazaar%2C_Mountains%2C_Nepal.jpg", "author": "Vyacheslav Argenberg", "source": "https://commons.wikimedia.org/wiki/File:Namche_Bazaar,_Mountains,_Nepal.jpg", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "area_caption": "Namche Bazaar, Khumbu", "area_caption_np": "नाम्चे बजार, खुम्बु"}]');
INSERT INTO public.listings VALUES (7, 'sightseeing', 'Pashupatinath Temple Tour', 'पशुपतिनाथ मन्दिर भ्रमण', 'A guided half-day tour of one of the holiest Hindu temples in the world.', 'बागमती किनारमा रहेको हिन्दूहरूको पवित्र पशुपतिनाथ मन्दिर र यसको आसपासको निर्देशित भ्रमण।', 'Kathmandu', 'Pashupatinath', 27.7106000, 85.3486000, 35.00, 1, 20, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/The_Pashupatinath_Temple_27.jpg/1280px-The_Pashupatinath_Temple_27.jpg', '2026-09-25 11:51:37.510073', NULL, NULL, NULL, NULL, NULL, '{"Licensed city guide","Hotel pickup in Kathmandu"}', '{"Entrance fees",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/The_Pashupatinath_Temple_27.jpg/1280px-The_Pashupatinath_Temple_27.jpg", "author": "Nabin K. Sapkota", "source": "https://commons.wikimedia.org/wiki/File:The_Pashupatinath_Temple_27.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (8, 'sightseeing', 'Bhaktapur Durbar Square Tour', 'भक्तपुर दरबार क्षेत्र भ्रमण', 'Explore the ancient royal palace complex and medieval Newari architecture.', 'मध्यकालीन नेवारी कला, मन्दिर र दरबारले भरिएको भक्तपुर दरबार क्षेत्रको निर्देशित भ्रमण।', 'Bhaktapur', 'Durbar Square', 27.6710000, 85.4298000, 35.00, 1, 20, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Bhaktapur_Durbar_Square_7.jpg/1280px-Bhaktapur_Durbar_Square_7.jpg', '2026-09-25 11:51:37.510073', NULL, NULL, NULL, NULL, NULL, '{"Licensed city guide","Return transport from Kathmandu"}', '{"Entrance fees",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Bhaktapur_Durbar_Square_7.jpg/1280px-Bhaktapur_Durbar_Square_7.jpg", "author": "Janak Bhatta", "source": "https://commons.wikimedia.org/wiki/File:Bhaktapur_Durbar_Square_7.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (9, 'sightseeing', 'Phewa Lake Boating Tour', 'फेवा ताल डुङ्गा सवारी', 'A relaxing boat ride on Pokhara''s iconic lake with mountain views.', 'माछापुच्छ्रेको प्रतिबिम्ब देखिने फेवा तालमा रंगीन डुंगा सयर र ताल बाराही मन्दिर भ्रमण।', 'Pokhara', 'Phewa Lake', 28.2096000, 83.9560000, 15.00, 1, 6, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Phewa_lake_2604.jpg/1280px-Phewa_lake_2604.jpg', '2026-09-25 11:51:37.510073', NULL, NULL, NULL, NULL, NULL, '{"Boat and boatman","Life jackets"}', '{"Tal Barahi temple offerings",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Phewa_lake_2604.jpg/1280px-Phewa_lake_2604.jpg", "author": "Bijay Chaurasia", "source": "https://commons.wikimedia.org/wiki/File:Phewa_lake_2604.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (10, 'trek', 'Annapurna Circuit Trek', 'अन्नपूर्ण सर्किट पदयात्रा', 'A classic loop around the Annapurna massif, crossing the high Thorong La pass from green valleys into the dry Mustang landscape.', 'हरियो उपत्यकाबाट उच्च थोराङ ला भञ्ज्याङ पार गर्दै सुख्खा मुस्ताङतर्फ जाने अन्नपूर्ण हिमशृङ्खलाको परिक्रमा।', 'Manang', 'Besisahar to Jomsom via Thorong La', 28.6667000, 84.0167000, 1100.00, 12, 12, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Thorong_La_Pass.jpg/1280px-Thorong_La_Pass.jpg', '2026-11-17 23:17:36.18136', 'challenging', 5416, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Drive Kathmandu to Chamje"}, {"day": "2", "title": "Trek to Dharapani"}, {"day": "3", "title": "Trek to Chame"}, {"day": "4", "title": "Trek to Upper Pisang"}, {"day": "5", "title": "Trek to Manang via Ngawal"}, {"day": "6", "title": "Acclimatisation day in Manang"}, {"day": "7", "title": "Trek to Yak Kharka"}, {"day": "8", "title": "Trek to Thorong Phedi"}, {"day": "9", "title": "Cross Thorong La, descend to Muktinath"}, {"day": "10", "title": "Trek to Jomsom"}, {"day": "11", "title": "Fly Jomsom to Pokhara"}, {"day": "12", "title": "Drive to Kathmandu"}]', '{"Trekking permits","Licensed trekking guide","Teahouse accommodation","Ground transport per itinerary"}', '{"International flights","Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Muktinath_Valley%2C_View_of_Thorong_La_Pass%2C_Mountains%2C_Nepal.jpg/1280px-Muktinath_Valley%2C_View_of_Thorong_La_Pass%2C_Mountains%2C_Nepal.jpg}', '[[28.2310, 84.3790], [28.5520, 84.2400], [28.6667, 84.0167], [28.7930, 83.9380], [28.8170, 83.8720], [28.7800, 83.7300]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Thorong_La_Pass.jpg/1280px-Thorong_La_Pass.jpg", "author": "Vaupk12", "source": "https://commons.wikimedia.org/wiki/File:Thorong_La_Pass.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Muktinath_Valley%2C_View_of_Thorong_La_Pass%2C_Mountains%2C_Nepal.jpg/1280px-Muktinath_Valley%2C_View_of_Thorong_La_Pass%2C_Mountains%2C_Nepal.jpg", "author": "Vyacheslav Argenberg", "source": "https://commons.wikimedia.org/wiki/File:Muktinath_Valley,_View_of_Thorong_La_Pass,_Mountains,_Nepal.jpg", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0"}]');
INSERT INTO public.listings VALUES (11, 'trek', 'Langtang Valley Trek', 'लाङटाङ उपत्यका पदयात्रा', 'A short trek north of Kathmandu through Tamang villages and rhododendron forest to Kyanjin Gompa, surrounded by glaciers.', 'काठमाडौंको उत्तरमा तामाङ गाउँ र लालीगुराँसको जंगल हुँदै हिमनदीले घेरिएको क्यान्जिन गुम्बासम्मको छोटो पदयात्रा।', 'Rasuwa', 'Syabrubesi to Kyanjin Gompa', 28.2110000, 85.5620000, 650.00, 8, 12, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Stupa_in_between_Langtang_valley_and_Kyanjin.jpg/1280px-Stupa_in_between_Langtang_valley_and_Kyanjin.jpg', '2026-11-17 23:17:36.18136', 'moderate', 4773, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Drive Kathmandu to Syabrubesi"}, {"day": "2", "title": "Trek to Lama Hotel"}, {"day": "3", "title": "Trek to Langtang Village"}, {"day": "4", "title": "Trek to Kyanjin Gompa"}, {"day": "5", "title": "Day hike to Kyanjin Ri"}, {"day": "6", "title": "Trek to Lama Hotel"}, {"day": "7", "title": "Trek to Syabrubesi"}, {"day": "8", "title": "Drive to Kathmandu"}]', '{"Trekking permits","Licensed trekking guide","Teahouse accommodation","Kathmandu–Syabrubesi transport"}', '{"Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Chorten_in_the_Langtang_valley_03.jpg/1280px-Chorten_in_the_Langtang_valley_03.jpg}', '[[28.1610, 85.3460], [28.1660, 85.4300], [28.2140, 85.5180], [28.2110, 85.5620]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Stupa_in_between_Langtang_valley_and_Kyanjin.jpg/1280px-Stupa_in_between_Langtang_valley_and_Kyanjin.jpg", "author": "Sunny Shrestha", "source": "https://commons.wikimedia.org/wiki/File:Stupa_in_between_Langtang_valley_and_Kyanjin.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Chorten_in_the_Langtang_valley_03.jpg/1280px-Chorten_in_the_Langtang_valley_03.jpg", "author": "Rsh2020", "source": "https://commons.wikimedia.org/wiki/File:Chorten_in_the_Langtang_valley_03.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (12, 'trek', 'Manaslu Circuit Trek', 'मनास्लु सर्किट पदयात्रा', 'A remote circuit around the world''s eighth-highest mountain, crossing Larkya La through Gurung and Tibetan-influenced villages.', 'संसारको आठौं अग्लो हिमाल मनास्लुको परिक्रमा, गुरुङ र तिब्बती संस्कृतिका गाउँ हुँदै लार्क्या ला पार गर्दै।', 'Gorkha', 'Machha Khola to Dharapani via Larkya La', 28.5850000, 84.6360000, 1350.00, 13, 10, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Mt_Manaslu.jpg/1280px-Mt_Manaslu.jpg', '2026-11-17 23:17:36.18136', 'strenuous', 5106, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Drive Kathmandu to Machha Khola"}, {"day": "2", "title": "Trek to Jagat"}, {"day": "3", "title": "Trek to Deng"}, {"day": "4", "title": "Trek to Namrung"}, {"day": "5", "title": "Trek to Lho"}, {"day": "6", "title": "Trek to Samagaun"}, {"day": "7", "title": "Acclimatisation day in Samagaun"}, {"day": "8", "title": "Trek to Samdo"}, {"day": "9", "title": "Trek to Dharamsala"}, {"day": "10", "title": "Cross Larkya La, descend to Bimthang"}, {"day": "11", "title": "Trek to Tilije"}, {"day": "12", "title": "Trek to Dharapani, drive to Besisahar"}, {"day": "13", "title": "Drive to Kathmandu"}]', '{"Restricted area permit","Trekking permits","Licensed trekking guide","Teahouse accommodation","Ground transport per itinerary"}', '{"International flights","Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Manaslu_range.jpg/1280px-Manaslu_range.jpg}', '[[28.2280, 84.8750], [28.3370, 84.8970], [28.5850, 84.6360], [28.6680, 84.5390], [28.6370, 84.4220], [28.5330, 84.3640]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Mt_Manaslu.jpg/1280px-Mt_Manaslu.jpg", "author": "Pratapgrg", "source": "https://commons.wikimedia.org/wiki/File:Mt_Manaslu.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Manaslu_range.jpg/1280px-Manaslu_range.jpg", "author": "Samdesherpa", "source": "https://commons.wikimedia.org/wiki/File:Manaslu_range.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (13, 'trek', 'Mardi Himal Trek', 'मार्दी हिमाल पदयात्रा', 'A quieter ridge trek near Pokhara with close-up views of Machhapuchhre and the Annapurna range.', 'पोखरानजिकै माछापुच्छ्रे र अन्नपूर्ण हिमशृङ्खलाको नजिकको दृश्य दिने शान्त डाँडाको पदयात्रा।', 'Pokhara', 'Kande to Mardi Himal View Point', 28.4480000, 83.9070000, 450.00, 6, 12, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Yaks_on_the_Mardi_Himal_trek.jpg/1280px-Yaks_on_the_Mardi_Himal_trek.jpg', '2026-11-17 23:17:36.18136', 'moderate', 4500, 'Mar–May, Sep–Nov', 'वसन्त र शरद ऋतु', '[{"day": "1", "title": "Drive Pokhara to Kande, trek to Deurali"}, {"day": "2", "title": "Trek to Forest Camp"}, {"day": "3", "title": "Trek to High Camp"}, {"day": "4", "title": "Hike to the view point, descend to Badal Danda"}, {"day": "5", "title": "Trek to Siding village"}, {"day": "6", "title": "Drive to Pokhara"}]', '{"Trekking permits","Licensed trekking guide","Teahouse accommodation","Pokhara–Kande transport"}', '{"Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Mardi_Himal_basecamp_panorama.jpg/1280px-Mardi_Himal_basecamp_panorama.jpg}', '[[28.2780, 83.8180], [28.3500, 83.8500], [28.4480, 83.9070], [28.4650, 83.9180]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Yaks_on_the_Mardi_Himal_trek.jpg/1280px-Yaks_on_the_Mardi_Himal_trek.jpg", "author": "Rajan Karki", "source": "https://commons.wikimedia.org/wiki/File:Yaks_on_the_Mardi_Himal_trek.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Mardi_Himal_basecamp_panorama.jpg/1280px-Mardi_Himal_basecamp_panorama.jpg", "author": "Nrik kiran", "source": "https://commons.wikimedia.org/wiki/File:Mardi_Himal_basecamp_panorama.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (14, 'trek', 'Upper Mustang Trek', 'माथिल्लो मुस्ताङ पदयात्रा', 'A journey into the former Kingdom of Lo, with cave dwellings, red cliffs and the walled city of Lo Manthang.', 'गुफा, रातो चट्टान र पर्खालले घेरिएको लोमान्थाङ सहर भएको पुरानो लो राज्यतर्फको यात्रा।', 'Mustang', 'Jomsom to Lo Manthang', 29.1830000, 83.9590000, 2100.00, 12, 10, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Mustang-Lo_Manthang-14-Dachausflug-2015-gje.jpg/1280px-Mustang-Lo_Manthang-14-Dachausflug-2015-gje.jpg', '2026-11-17 23:17:36.18136', 'moderate', 3840, 'Mar–Nov', 'चैतदेखि मंसिरसम्म', '[{"day": "1", "title": "Fly Pokhara to Jomsom, trek to Kagbeni"}, {"day": "2", "title": "Trek to Chele"}, {"day": "3", "title": "Trek to Syangboche"}, {"day": "4", "title": "Trek to Ghami"}, {"day": "5", "title": "Trek to Charang"}, {"day": "6", "title": "Trek to Lo Manthang"}, {"day": "7", "title": "Explore Lo Manthang"}, {"day": "8", "title": "Trek to Drakmar"}, {"day": "9", "title": "Trek to Ghiling"}, {"day": "10", "title": "Trek to Chhusang"}, {"day": "11", "title": "Trek to Jomsom"}, {"day": "12", "title": "Fly to Pokhara"}]', '{"Restricted area permit","Trekking permits","Licensed trekking guide","Teahouse accommodation","Pokhara–Jomsom return flights"}', '{"International flights","Travel insurance","Meals not listed","Personal expenses and tips"}', NULL, NULL, '{https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Lo_Manthang_Royal_Palace.JPG/1280px-Lo_Manthang_Royal_Palace.JPG}', '[[28.7800, 83.7300], [28.8370, 83.7830], [28.9150, 83.8170], [29.0500, 83.8800], [29.1830, 83.9590]]', '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Mustang-Lo_Manthang-14-Dachausflug-2015-gje.jpg/1280px-Mustang-Lo_Manthang-14-Dachausflug-2015-gje.jpg", "author": "Gerd Eichmann", "source": "https://commons.wikimedia.org/wiki/File:Mustang-Lo_Manthang-14-Dachausflug-2015-gje.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}, {"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Lo_Manthang_Royal_Palace.JPG/1280px-Lo_Manthang_Royal_Palace.JPG", "author": "Wimbex", "source": "https://commons.wikimedia.org/wiki/File:Lo_Manthang_Royal_Palace.JPG", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0"}]');
INSERT INTO public.listings VALUES (15, 'hotel', 'Sauraha Riverside Lodge', 'सौराहा रिभरसाइड लज', 'A jungle lodge on the Rapti River at the edge of Chitwan National Park, a short walk from safari departures.', 'चितवन राष्ट्रिय निकुञ्जको छेउमा राप्ती नदी किनारको जंगल लज, सफारी सुरु हुने ठाउँबाट नजिकै।', 'Chitwan', 'Sauraha', 27.5760000, 84.4960000, 80.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Rapti_River%2C_Sauraha%2C_Chitwan.jpg/1280px-Rapti_River%2C_Sauraha%2C_Chitwan.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Free Wi-Fi","Swimming pool",Restaurant,"River views","Safari desk","Breakfast included"}', 4, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Rapti_River%2C_Sauraha%2C_Chitwan.jpg/1280px-Rapti_River%2C_Sauraha%2C_Chitwan.jpg", "author": "Ajay Gautam", "source": "https://commons.wikimedia.org/wiki/File:Rapti_River,_Sauraha,_Chitwan.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "area_caption": "Rapti River, Sauraha", "area_caption_np": "राप्ती नदी, सौराहा"}]');
INSERT INTO public.listings VALUES (16, 'hotel', 'Nagarkot Himalayan View Resort', 'नगरकोट हिमालयन भ्यु रिसोर्ट', 'A hilltop resort east of Kathmandu, known for sunrise views stretching across the Himalaya.', 'काठमाडौंको पूर्वमा डाँडामाथि रहेको रिसोर्ट, हिमालमाथिको सूर्योदय दृश्यका लागि परिचित।', 'Nagarkot', 'Nagarkot ridge', 27.7150000, 85.5200000, 60.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Le_Langtang_Lirung_%28Himalaya%2C_N%C3%A9pal%29_%288448200379%29.jpg/1280px-Le_Langtang_Lirung_%28Himalaya%2C_N%C3%A9pal%29_%288448200379%29.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Free Wi-Fi",Restaurant,"Mountain views",Terrace,"Breakfast included"}', 3, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Le_Langtang_Lirung_%28Himalaya%2C_N%C3%A9pal%29_%288448200379%29.jpg/1280px-Le_Langtang_Lirung_%28Himalaya%2C_N%C3%A9pal%29_%288448200379%29.jpg", "author": "Jean-Pierre Dalbéra", "source": "https://commons.wikimedia.org/wiki/File:Le_Langtang_Lirung_(Himalaya,_N%C3%A9pal)_(8448200379).jpg", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "area_caption": "Langtang Lirung seen from Nagarkot", "area_caption_np": "नगरकोटबाट देखिएको लाङटाङ लिरुङ"}]');
INSERT INTO public.listings VALUES (17, 'hotel', 'Lumbini Garden Retreat', 'लुम्बिनी गार्डेन रिट्रिट', 'A calm garden hotel near the Lumbini monastic zone, the birthplace of the Buddha.', 'भगवान बुद्धको जन्मस्थल लुम्बिनीको विहार क्षेत्रनजिकै रहेको शान्त बगैंचायुक्त होटल।', 'Lumbini', 'Near the Lumbini monastic zone', 27.4840000, 83.2760000, 45.00, NULL, NULL, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Lumbini_World_Heritage_Site-IMG_7327.jpg/1280px-Lumbini_World_Heritage_Site-IMG_7327.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Free Wi-Fi",Restaurant,Garden,"Bicycle rental","Breakfast available"}', 3, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Lumbini_World_Heritage_Site-IMG_7327.jpg/1280px-Lumbini_World_Heritage_Site-IMG_7327.jpg", "author": "Bijay Chaurasia", "source": "https://commons.wikimedia.org/wiki/File:Lumbini_World_Heritage_Site-IMG_7327.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "area_caption": "Maya Devi Temple, Lumbini", "area_caption_np": "मायादेवी मन्दिर, लुम्बिनी"}]');
INSERT INTO public.listings VALUES (18, 'sightseeing', 'Boudhanath Stupa Tour', 'बौद्धनाथ स्तूप भ्रमण', 'Walk the kora around one of the largest stupas in the world, surrounded by monasteries and butter-lamp shops.', 'गुम्बा र बत्ती पसलहरूले घेरिएको संसारकै ठूला स्तूपमध्ये एक बौद्धनाथको परिक्रमा।', 'Kathmandu', 'Boudha', 27.7215000, 85.3620000, 30.00, 1, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Boudha_Stupa_2018_04.jpg/1280px-Boudha_Stupa_2018_04.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Licensed city guide","Hotel pickup in Kathmandu"}', '{"Entrance fees",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Boudha_Stupa_2018_04.jpg/1280px-Boudha_Stupa_2018_04.jpg", "author": "Nabin K. Sapkota", "source": "https://commons.wikimedia.org/wiki/File:Boudha_Stupa_2018_04.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (19, 'sightseeing', 'Swayambhunath Tour', 'स्वयम्भूनाथ भ्रमण', 'Climb to the hilltop stupa known as the Monkey Temple for sweeping views over the Kathmandu Valley.', 'बाँदर मन्दिरका नामले चिनिने डाँडामाथिको स्तूपसम्म चढेर काठमाडौं उपत्यकाको फराकिलो दृश्य।', 'Kathmandu', 'Swayambhu hill', 27.7149000, 85.2904000, 30.00, 1, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Swayambhu%2C_Kathmandu%2C_Nepal.jpg/1280px-Swayambhu%2C_Kathmandu%2C_Nepal.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Licensed city guide","Hotel pickup in Kathmandu"}', '{"Entrance fees",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Swayambhu%2C_Kathmandu%2C_Nepal.jpg/1280px-Swayambhu%2C_Kathmandu%2C_Nepal.jpg", "author": "Vyacheslav Argenberg", "source": "https://commons.wikimedia.org/wiki/File:Swayambhu,_Kathmandu,_Nepal.jpg", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0"}]');
INSERT INTO public.listings VALUES (20, 'sightseeing', 'Kathmandu Durbar Square Tour', 'काठमाडौं दरबार क्षेत्र भ्रमण', 'Explore the old royal palace square with its pagoda temples, Kumari Ghar and Newar woodcarving.', 'प्यागोडा मन्दिर, कुमारी घर र नेवारी काष्ठकलासहितको पुरानो राजदरबार क्षेत्रको भ्रमण।', 'Kathmandu', 'Basantapur', 27.7045000, 85.3070000, 35.00, 1, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Kathmandu_Durbar_Square%2C_Shiva_Parvati_Temple%2C_Nepal_%28edit%29.jpg/1280px-Kathmandu_Durbar_Square%2C_Shiva_Parvati_Temple%2C_Nepal_%28edit%29.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Licensed city guide","Hotel pickup in Kathmandu"}', '{"Entrance fees",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Kathmandu_Durbar_Square%2C_Shiva_Parvati_Temple%2C_Nepal_%28edit%29.jpg/1280px-Kathmandu_Durbar_Square%2C_Shiva_Parvati_Temple%2C_Nepal_%28edit%29.jpg", "author": "Vyacheslav Argenberg (derivative work: UnpetitproleX)", "source": "https://commons.wikimedia.org/wiki/File:Kathmandu_Durbar_Square,_Shiva_Parvati_Temple,_Nepal_(edit).jpg", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0"}]');
INSERT INTO public.listings VALUES (21, 'sightseeing', 'Sarangkot Sunrise Tour', 'सराङकोट सूर्योदय भ्रमण', 'An early drive to Sarangkot hill to watch the sun rise over Machhapuchhre, Annapurna and Dhaulagiri.', 'माछापुच्छ्रे, अन्नपूर्ण र धौलागिरिमाथिको सूर्योदय हेर्न बिहानै सराङकोट डाँडाको यात्रा।', 'Pokhara', 'Sarangkot', 28.2440000, 83.9490000, 25.00, 1, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/View_of_Annapurna_South_and_Machapuchare_from_Sarangkot%2C_Nepal-WLV-1659.jpg/1280px-View_of_Annapurna_South_and_Machapuchare_from_Sarangkot%2C_Nepal-WLV-1659.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Return transport from Lakeside","Local guide"}', '{"View tower fee",Breakfast,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/View_of_Annapurna_South_and_Machapuchare_from_Sarangkot%2C_Nepal-WLV-1659.jpg/1280px-View_of_Annapurna_South_and_Machapuchare_from_Sarangkot%2C_Nepal-WLV-1659.jpg", "author": "Bijay Chaurasia", "source": "https://commons.wikimedia.org/wiki/File:View_of_Annapurna_South_and_Machapuchare_from_Sarangkot,_Nepal-WLV-1659.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (22, 'sightseeing', 'Davis Falls Visit', 'डेभिस फल्स (पाताले छाँगो) भ्रमण', 'See the waterfall where the Pardi Khola drops into an underground tunnel, known locally as Patale Chhango.', 'पर्दी खोला भूमिगत सुरुङमा खस्ने झरना, जसलाई स्थानीय रूपमा पाताले छाँगो भनिन्छ।', 'Pokhara', 'Chhorepatan', 28.1900000, 83.9590000, 15.00, 1, 20, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Davis_Falls-Pokhara_02.jpg/1280px-Davis_Falls-Pokhara_02.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Return transport from Lakeside"}', '{"Entrance fee",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Davis_Falls-Pokhara_02.jpg/1280px-Davis_Falls-Pokhara_02.jpg", "author": "Sabina Bajracharya", "source": "https://commons.wikimedia.org/wiki/File:Davis_Falls-Pokhara_02.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (23, 'sightseeing', 'World Peace Pagoda Hike', 'विश्व शान्ति स्तूप पदयात्रा', 'Cross Phewa Lake by boat and hike up to the white Peace Pagoda for panoramic views of Pokhara and the mountains.', 'फेवा ताल डुंगाले पार गरी सेतो शान्ति स्तूपसम्म पैदल उकालो, पोखरा र हिमालको मनोरम दृश्यसहित।', 'Pokhara', 'Anadu hill', 28.2010000, 83.9450000, 20.00, 1, 15, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/World_Peace_Pagoda%2C_Pokhara_by_Y7.jpg/1280px-World_Peace_Pagoda%2C_Pokhara_by_Y7.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Boat crossing","Local guide"}', '{Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/World_Peace_Pagoda%2C_Pokhara_by_Y7.jpg/1280px-World_Peace_Pagoda%2C_Pokhara_by_Y7.jpg", "author": "Yallu007", "source": "https://commons.wikimedia.org/wiki/File:World_Peace_Pagoda,_Pokhara_by_Y7.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (24, 'sightseeing', 'Gupteshwor Cave Tour', 'गुप्तेश्वर गुफा भ्रमण', 'Descend into a limestone cave with a sacred Shiva shrine and a view of Davis Falls from below.', 'शिवलिंग रहेको पवित्र चुनढुंगे गुफाभित्र झर्दै तलबाट डेभिस फल्सको दृश्य।', 'Pokhara', 'Chhorepatan', 28.1895000, 83.9601000, 15.00, 1, 20, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Gupteshwor_Cave_%2C_Pokhara.jpg/1280px-Gupteshwor_Cave_%2C_Pokhara.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Return transport from Lakeside"}', '{"Entrance fee",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Gupteshwor_Cave_%2C_Pokhara.jpg/1280px-Gupteshwor_Cave_%2C_Pokhara.jpg", "author": "Sushila Gurung", "source": "https://commons.wikimedia.org/wiki/File:Gupteshwor_Cave_,_Pokhara.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (25, 'sightseeing', 'Chitwan Jungle Safari', 'चितवन जंगल सफारी', 'A jeep safari through Chitwan National Park looking for one-horned rhinos, deer, crocodiles and birdlife.', 'एकसिंगे गैंडा, मृग, गोही र चराचुरुंगी हेर्दै चितवन राष्ट्रिय निकुञ्जभित्र जीप सफारी।', 'Chitwan', 'Chitwan National Park', 27.5750000, 84.4950000, 60.00, 1, 8, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Greater_one-horned_rhinoceros_at_Chitwan.jpg/1280px-Greater_one-horned_rhinoceros_at_Chitwan.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Jeep and driver","Naturalist guide"}', '{"National park entry fee",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Greater_one-horned_rhinoceros_at_Chitwan.jpg/1280px-Greater_one-horned_rhinoceros_at_Chitwan.jpg", "author": "Aditya Pal", "source": "https://commons.wikimedia.org/wiki/File:Greater_one-horned_rhinoceros_at_Chitwan.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
INSERT INTO public.listings VALUES (26, 'sightseeing', 'Rapti River Canoe Ride', 'राप्ती नदी डुंगा यात्रा', 'A quiet dugout canoe ride along the Rapti River, followed by a short jungle walk.', 'राप्ती नदीमा परम्परागत डुंगामा शान्त सयर र त्यसपछि छोटो जंगल पैदल यात्रा।', 'Chitwan', 'Rapti River, Sauraha', 27.5730000, 84.4900000, 35.00, 1, 8, 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Tourists_crossing_Rapti_river_in_a_boat_at_Sauraha_%2C_Chitwan.jpg/1280px-Tourists_crossing_Rapti_river_in_a_boat_at_Sauraha_%2C_Chitwan.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Canoe and boatman","Naturalist guide"}', '{"National park entry fee",Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Tourists_crossing_Rapti_river_in_a_boat_at_Sauraha_%2C_Chitwan.jpg/1280px-Tourists_crossing_Rapti_river_in_a_boat_at_Sauraha_%2C_Chitwan.jpg", "author": "Supradai", "source": "https://commons.wikimedia.org/wiki/File:Tourists_crossing_Rapti_river_in_a_boat_at_Sauraha_,_Chitwan.jpg", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0"}]');
INSERT INTO public.listings VALUES (27, 'sightseeing', 'Tharu Cultural Experience', 'थारु सांस्कृतिक अनुभव', 'Visit a Tharu village and watch a traditional stick dance performance in Sauraha.', 'थारु गाउँको भ्रमण र सौराहामा परम्परागत लठ्ठी नाच प्रदर्शन।', 'Chitwan', 'Sauraha', 27.5800000, 84.5000000, 20.00, 1, 20, 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Tharu_Dance_Sauraha_Chitwan_2018.jpg/1280px-Tharu_Dance_Sauraha_Chitwan_2018.jpg', '2026-11-17 23:17:36.18136', NULL, NULL, NULL, NULL, NULL, '{"Village guide","Cultural show ticket"}', '{Meals,Tips}', NULL, NULL, NULL, NULL, '[{"url": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Tharu_Dance_Sauraha_Chitwan_2018.jpg/1280px-Tharu_Dance_Sauraha_Chitwan_2018.jpg", "author": "Pratap Baniya", "source": "https://commons.wikimedia.org/wiki/File:Tharu_Dance_Sauraha_Chitwan_2018.jpg", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0"}]');
